use binary_merkle_root::binary_merkle_root;
use poseidon::poseidon::bn254::{hash_2, hash_3};

pub(crate) global MAX_DEPTH: u32 = 20;

// Domain separator for Poseidon3(issuer public key).
global LEAF_DOMAIN: Field =
    185404551131306766954100762329350135288498146007932686448214248919067924295;

pub(crate) fn root(
    public_key_x: Field,
    public_key_y: Field,
    depth: u32,
    indices: [bool; MAX_DEPTH],
    siblings: [Field; MAX_DEPTH],
) -> Field {
    assert(depth <= MAX_DEPTH, "issuer path depth exceeds the circuit maximum");
    let leaf = hash_3([LEAF_DOMAIN, public_key_x, public_key_y]);
    binary_merkle_root(hash_2, leaf, depth, indices, siblings)
}

// Pinned cross-language: the same leaves, roots and witnesses `packages/issuer-set/tests/cross-language.test.ts`
// and `packages/contracts/test/integration/IssuerSetCrossLanguageRoot.t.sol` pin, computed three
// independent ways before being copied here.
mod tests {
    use super::{root, MAX_DEPTH};
    use poseidon::poseidon::bn254::hash_2;

    // `k * Base8` on Baby Jubjub, for k = 1, 2, 5.
    global KEY_1_X: Field =
        5299619240641551281634865583518297030282874472190772894086521144482721001553;
    global KEY_1_Y: Field =
        16950150798460657717958625567821834550301663161624707787222815936182638968203;
    global KEY_2_X: Field =
        10031262171927540148667355526369034398030886437092045105752248699557385197826;
    global KEY_2_Y: Field =
        633281375905621697187330766174974863687049529291089048651929454608812697683;
    global KEY_5_X: Field =
        11480966271046430430613841218147196773252373073876138147006741179837832100836;
    global KEY_5_Y: Field =
        15148236048131954717802795400425086368006776860859772698778589175317365693546;

    global LEAF_OF_KEY_1: Field =
        2493720610778676091149258492386261697559719708118160248500693563612404203088;
    global LEAF_OF_KEY_2: Field =
        15278273562238927018842798161288898682472598529198791544673021966310311323458;
    global LEAF_OF_KEY_3: Field =
        20980331097734099105425623618460522669974741732319895218846623662978431137317;

    global ROOT_OF_KEYS_1_TO_2: Field =
        15680708859485847685012924683010191875504585065894243099617821723863156328943;
    global ROOT_OF_KEYS_1_2_3: Field =
        11334223563046274794300795549267186709638286758254539923752495560734019145426;
    global ROOT_OF_KEYS_1_TO_4: Field =
        1012468898015973113393162930052218519362020364191895474978289263522471748684;
    global ROOT_OF_KEYS_1_TO_5: Field =
        1509212439766155221370997401451147889947558708210956682611194460683115030117;

    #[test]
    fn one_key_root_is_the_leaf() {
        let indices: [bool; MAX_DEPTH] = [false; MAX_DEPTH];
        let siblings: [Field; MAX_DEPTH] = [0; MAX_DEPTH];

        assert(root(KEY_1_X, KEY_1_Y, 0, indices, siblings) == LEAF_OF_KEY_1);
    }

    #[test]
    fn two_keys_hash_once() {
        let indices: [bool; MAX_DEPTH] = [false; MAX_DEPTH];
        let mut siblings: [Field; MAX_DEPTH] = [0; MAX_DEPTH];
        siblings[0] = LEAF_OF_KEY_2;

        assert(root(KEY_1_X, KEY_1_Y, 1, indices, siblings) == ROOT_OF_KEYS_1_TO_2);
    }

    #[test]
    fn key_2_opens_root_of_keys_1_2_3() {
        let mut indices: [bool; MAX_DEPTH] = [false; MAX_DEPTH];
        let mut siblings: [Field; MAX_DEPTH] = [0; MAX_DEPTH];
        indices[0] = true;
        siblings[0] = LEAF_OF_KEY_1;
        siblings[1] = LEAF_OF_KEY_3;

        assert(root(KEY_2_X, KEY_2_Y, 2, indices, siblings) == ROOT_OF_KEYS_1_2_3);
    }

    // Slot 4 of a five-slot set: levels 0 and 1 are promoted (no sibling), so the witness holds
    // only the one sibling at the level that does have one.
    #[test]
    fn promoted_levels_are_absent_from_the_witness() {
        let mut indices: [bool; MAX_DEPTH] = [false; MAX_DEPTH];
        let mut siblings: [Field; MAX_DEPTH] = [0; MAX_DEPTH];
        indices[0] = true;
        siblings[0] = ROOT_OF_KEYS_1_TO_4;

        assert(root(KEY_5_X, KEY_5_Y, 1, indices, siblings) == ROOT_OF_KEYS_1_TO_5);
    }

    #[test]
    fn padding_tail_is_ignored() {
        let mut indices: [bool; MAX_DEPTH] = [false; MAX_DEPTH];
        let mut siblings: [Field; MAX_DEPTH] = [0; MAX_DEPTH];
        siblings[0] = LEAF_OF_KEY_2;
        // Garbage past `depth`: binary_merkle_root only folds the first `depth` levels.
        indices[7] = true;
        siblings[3] = 999;

        assert(root(KEY_1_X, KEY_1_Y, 1, indices, siblings) == ROOT_OF_KEYS_1_TO_2);
    }

    #[test]
    fn depth_off_by_one_changes_root() {
        let mut indices: [bool; MAX_DEPTH] = [false; MAX_DEPTH];
        let mut siblings: [Field; MAX_DEPTH] = [0; MAX_DEPTH];
        indices[0] = true;
        siblings[0] = LEAF_OF_KEY_1;
        siblings[1] = LEAF_OF_KEY_3;

        // The true witness needs depth 2; stopping one level short must not silently agree.
        assert(root(KEY_2_X, KEY_2_Y, 1, indices, siblings) != ROOT_OF_KEYS_1_2_3);
    }

    #[test(should_fail_with = "issuer path depth exceeds the circuit maximum")]
    fn rejects_depth_above_max() {
        let indices: [bool; MAX_DEPTH] = [false; MAX_DEPTH];
        let siblings: [Field; MAX_DEPTH] = [0; MAX_DEPTH];

        let _ = root(KEY_1_X, KEY_1_Y, MAX_DEPTH + 1, indices, siblings);
    }

    #[test]
    fn accepts_depth_at_max() {
        let indices: [bool; MAX_DEPTH] = [false; MAX_DEPTH];
        let siblings: [Field; MAX_DEPTH] = [0; MAX_DEPTH];

        let mut expected = LEAF_OF_KEY_1;
        for _ in 0..MAX_DEPTH {
            expected = hash_2([expected, 0]);
        }

        assert(root(KEY_1_X, KEY_1_Y, MAX_DEPTH, indices, siblings) == expected);
    }

    // key_2_opens_root_of_keys_1_2_3's own witness is only valid at depth 2; running it one level
    // too deep must not silently still agree with ROOT_OF_KEYS_1_2_3.
    #[test]
    fn depth_above_the_true_one_changes_root() {
        let mut indices: [bool; MAX_DEPTH] = [false; MAX_DEPTH];
        let mut siblings: [Field; MAX_DEPTH] = [0; MAX_DEPTH];
        indices[0] = true;
        siblings[0] = LEAF_OF_KEY_1;
        siblings[1] = LEAF_OF_KEY_3;

        assert(root(KEY_2_X, KEY_2_Y, 3, indices, siblings) != ROOT_OF_KEYS_1_2_3);
    }
}

54.source:
mod credential;
mod eddsa;
mod issuer;
mod types;

use eddsa::eddsa_verify;
use issuer::MAX_DEPTH as ISSUER_SET_MAX_DEPTH;
use lean_imt_plus::lean_imt_plus_root;
use poseidon::poseidon::bn254::{hash_2, hash_3, hash_4};
use poseidon::poseidon::PoseidonHasher;
use types::Credential;

global REVOCATION_MAX_DEPTH: u32 = 20;
// keccak256(utf8("urn:cn:presentation:v1")) >> 8
global PRESENTATION_DOMAIN: Field =
    47717037732995119958831198142288202228464361330145547649000821135537239485;

fn main(
    current_time: pub u64,
    challenge: pub Field,
    audience: pub Field,
    required_programme_hash: pub Field,
    required_country_code: pub Field,
    credential: Credential,
    issuer_pub_x: Field,
    issuer_pub_y: Field,
    issuer_sig_r8_x: Field,
    issuer_sig_r8_y: Field,
    issuer_sig_s: Field,
    issuer_depth: u32,
    issuer_indices: [bool; ISSUER_SET_MAX_DEPTH],
    issuer_siblings: [Field; ISSUER_SET_MAX_DEPTH],
    device_pub_x: [u8; 32],
    device_pub_y: [u8; 32],
    device_signature: [u8; 64],
    identity_pub_x: Field,
    identity_pub_y: Field,
    identity_sig_r8_x: Field,
    identity_sig_r8_y: Field,
    identity_sig_s: Field,
    revocation_pub_x: Field,
    revocation_pub_y: Field,
    revocation_sig_r8_x: Field,
    revocation_sig_r8_y: Field,
    revocation_sig_s: Field,
    revocation_low_leaf_value: Field,
    revocation_low_leaf_next: Field,
    revocation_depth: u32,
    revocation_indices: [bool; REVOCATION_MAX_DEPTH],
    revocation_siblings: [Field; REVOCATION_MAX_DEPTH],
) -> pub (Field, Field) {
    let credential_message = credential::commitment(credential);

    assert(
        eddsa_verify::<PoseidonHasher>(
            issuer_pub_x,
            issuer_pub_y,
            issuer_sig_s,
            issuer_sig_r8_x,
            issuer_sig_r8_y,
            credential_message,
        ),
        "invalid issuer signature",
    );
    let approved_issuer_root =
        issuer::root(issuer_pub_x, issuer_pub_y, issuer_depth, issuer_indices, issuer_siblings);

    assert(credential.not_before <= current_time, "credential is not yet valid");
    assert(current_time <= credential.expires_at, "credential has expired");
    assert_eq(credential.programme_hash, required_programme_hash, "programme does not match");
    assert_eq(credential.country_code, required_country_code, "country does not match");

    let session_message = hash_4(
        [PRESENTATION_DOMAIN, challenge, audience, credential_message],
    );
    let session_message_bytes: [u8; 32] = session_message.to_be_bytes();
    assert_eq(
        credential::device_key_commitment(device_pub_x, device_pub_y),
        credential.device_key_commitment,
        "device key does not open the credential commitment",
    );
    assert(
        std::ecdsa_secp256r1::verify_signature(
            device_pub_x,
            device_pub_y,
            device_signature,
            session_message_bytes,
        ),
        "invalid device signature",
    );

    assert_eq(
        hash_2([identity_pub_x, identity_pub_y]),
        credential.holder_key_commitment,
        "identity key does not open the credential commitment",
    );
    assert(
        eddsa_verify::<PoseidonHasher>(
            identity_pub_x,
            identity_pub_y,
            identity_sig_s,
            identity_sig_r8_x,
            identity_sig_r8_y,
            session_message,
        ),
        "invalid identity signature",
    );

    assert_eq(
        hash_2([revocation_pub_x, revocation_pub_y]),
        credential.revocation_commitment,
        "revocation key does not open the credential commitment",
    );
    assert(
        eddsa_verify::<PoseidonHasher>(
            revocation_pub_x,
            revocation_pub_y,
            revocation_sig_s,
            revocation_sig_r8_x,
            revocation_sig_r8_y,
            session_message,
        ),
        "invalid revocation-key signature",
    );

    let revocation_root = lean_imt_plus_root(
        hash_3,
        hash_2,
        true,
        credential.revocation_commitment,
        revocation_low_leaf_value,
        revocation_low_leaf_next,
        revocation_depth,
        revocation_indices,
        revocation_siblings,
    );
    let empty_registry = revocation_depth == 0;
    assert(!empty_registry | (revocation_low_leaf_value == 0), "invalid empty revocation witness");
    assert(!empty_registry | (revocation_low_leaf_next == 0), "invalid empty revocation witness");
    for i in 0..REVOCATION_MAX_DEPTH {
        assert(!empty_registry | !revocation_indices[i], "invalid empty revocation witness");
        assert(!empty_registry | (revocation_siblings[i] == 0), "invalid empty revocation witness");
    }

    let canonical_revocation_root = if empty_registry { 0 } else { revocation_root };

    (approved_issuer_root, canonical_revocation_root)
}

#[test]
fn accepts_zk_kit_vector() {
    let pub_x = 17145850796026918084964381264224969058280635207741849259441085610619323268793;
    let pub_y = 12739136082614649000971099828843750903333050161922102230327542411762042864532;
    let r8_x = 15524625270731079305966391574257085402945890677596245735016312557711871251745;
    let r8_y = 21851585646035144628054782655502377976073920894610191532514047740161645049816;
    let s = 546000471566828313746526008704952611728577210855060032957183501675256683918;

    assert(eddsa_verify::<PoseidonHasher>(pub_x, pub_y, s, r8_x, r8_y, 42));
    assert(!eddsa_verify::<PoseidonHasher>(pub_x, pub_y, s, r8_x, r8_y, 43));
}

56.source:
// This circuit is designed to calculate the root of a binary Merkle
// tree given a hash function, a leaf, its depth, and the necessary sibling
// information (aka proof of membership).
// A circuit is designed without the capability to iterate through
// a dynamic array. To address this, a parameter with the static maximum
// tree depth is defined (i.e. 'MAX_DEPTH'). And additionally, the circuit
// receives a dynamic depth as an input, which is utilized in calculating the
// true root of the Merkle tree. The actual depth of the Merkle tree
// may be equal to or less than the static maximum depth.
pub fn binary_merkle_root<let MAX_DEPTH: u32>(
    hasher: fn([Field; 2]) -> Field,
    leaf: Field,
    depth: u32,
    indices: [bool; MAX_DEPTH],
    siblings: [Field; MAX_DEPTH],
) -> Field {
    // Start from the leaf node
    let mut node = leaf;

    // Iterate through the Merkle proof up to MAX_DEPTH
    for i in 0..MAX_DEPTH {
        // Only compute hash if the current level is within the tree depth
        if i < depth {
            let sibling = siblings[i];

            // Determine the ordering of node and sibling based on the index bit
            // If indices[i] is false, node is on the left; otherwise, it's on the right
            let (left, right) = if !indices[i] {
                (node, sibling)
            } else {
                (sibling, node)
            };

            // Hash the pair to move one level up the tree
            node = hasher([left, right]);
        }
    }

    // Return the root computed
    node
}

58.source:
mod scalar_field;
mod test;
pub mod bjj;

pub use crate::scalar_field::ScalarField;
use std::ops::{Add, Neg, Sub};

pub struct Curve<Params> {
    pub x: Field,
    pub y: Field,
}

// ####################################################################################################################
// ####################################################################################################################
// ### T R A I T S
// ####################################################################################################################
// ####################################################################################################################

/// Parametrises a Twisted Edwards curve
trait TECurveParameterTrait {
    fn a() -> Field; // twisted edward curve parameter a
    fn d() -> Field; // twisted edward curve parameter d
    fn gen() -> (Field, Field); // generator point x/y coordinates
}

/// Defines methods that a valid Curve implementation must satisfy
pub trait CurveTrait<Params>: Add + Sub + Eq + Neg + Default {
    fn new(x: Field, y: Field) -> Self;
    fn zero() -> Self;
    fn one() -> Self;
    fn dbl(self) -> Self;
    fn mul<let NScalarSlices: u32>(self, x: ScalarField<NScalarSlices>) -> Self;
    fn msm<let N: u32, let NScalarSlices: u32>(
        points: [Self; N],
        scalars: [ScalarField<NScalarSlices>; N],
    ) -> Self;

    fn eq(self, x: Self) -> bool {
        self == x
    }
    fn is_zero(self) -> bool {
        self == Self::zero()
    }

    fn is_on_curve(self) -> bool;
    fn assert_is_on_curve(self);
    fn assert_equal(self, other: Self);
}

// ####################################################################################################################
// ####################################################################################################################
// ### C O N S T R A I N E D    F U N C T I O N S
// ####################################################################################################################
// ####################################################################################################################
impl<Params> std::default::Default for Curve<Params>
where
    Params: TECurveParameterTrait,
{
    /// Returns point at infinity
    ///
    /// Cost: 0 gates
    fn default() -> Self {
        Curve::zero()
    }
}

impl<Params> std::ops::Add for Curve<Params>
where
    Params: TECurveParameterTrait,
{
    /// Compute `self + other`
    ///
    /// Cost: 7 gates
    fn add(self, other: Self) -> Self {
        Curve::add_internal(self, other, Params::a(), Params::d())
    }
}

impl<Params> std::ops::Neg for Curve<Params> {
    /// Negate a point
    ///
    /// Cost: usually 0, will cost 1 gate if the `x` coordinate needs to be converted into a witness
    fn neg(self) -> Self {
        Curve { x: -self.x, y: self.y }
    }
}

impl<Params> std::ops::Sub for Curve<Params>
where
    Params: TECurveParameterTrait,
{
    /// Compute `self - other`
    ///
    /// Cost: 7 gates
    fn sub(self, other: Self) -> Self {
        Curve::add_internal(self, other.neg(), Params::a(), Params::d())
    }
}

impl<Params> std::cmp::Eq for Curve<Params> {
    /// Compute `self == other`
    ///
    /// Cost: 6 gates
    fn eq(self, other: Self) -> bool {
        (self.x == other.x) & (self.y == other.y)
    }
}

impl<Params> std::convert::From<(Field, Field)> for Curve<Params> {
    /// Construct from tuple of field elements
    ///
    /// Use this method instead of `new` if you know x/y is on the curve
    ///
    /// Cost: 0 gates
    fn from((x, y): (Field, Field)) -> Self {
        Curve { x, y }
    }
}

impl<Params> CurveTrait<Params> for Curve<Params>
where
    Params: TECurveParameterTrait,
{

    /// Construct a new point
    ///
    /// If you know the x/y coords form a valid point DO NOT USE THIS METHOD
    /// This method calls `assert_is_on_curve` which costs 3 gates.
    /// Instead, directly construct via Curve{x, y} or use from((x, y))
    ///
    /// Cost: 3 gates
    fn new(x: Field, y: Field) -> Self {
        let result = Curve { x, y };
        result.assert_is_on_curve();
        result
    }

    /// Return the Identity element (point at infinity)
    ///
    /// Cost: 0 gates
    fn zero() -> Self {
        Curve { x: 0, y: 1 }
    }

    /// Return the Generator of the group
    ///
    /// Cost: 0 gates (assuming Params trait returns values known at compile time!)
    fn one() -> Self {
        let (x, y) = Params::gen();
        Curve { x, y }
    }

    /// Validate a point is on the curve
    ///
    /// cheaper than `is_on_curve` (assert is cheaper than returning a bool)
    ///
    /// Cost: 3 gates
    fn assert_is_on_curve(self) {
        let t0 = self.x * self.x;
        let t1 = self.y * self.y;
        std::as_witness(t0);
        std::as_witness(t1);
        let t2 = Params::a() * t0 + t1;
        let t3 = 1 + Params::d() * t0 * t1;
        assert(t2 == t3);
    }

    /// Constrain two points to equal each other
    ///
    /// Cheaper than `assert(self == other)` because no need to return a bool
    ///
    /// Cost: 0-2 gates (can do these asserts with just copy constraints)
    fn assert_equal(self, other: Self) {
        assert(self.x == other.x);
        assert(self.y == other.y);
    }

    /// Return a bool that describes whether the point is on the curve
    ///
    /// If you don't need to handle the failure case, it is cheaper to call `assert_is_on_curve`
    ///
    /// Cost: 5 gates
    fn is_on_curve(self) -> bool {
        let t0 = self.x * self.x;
        let t1 = self.y * self.y;
        std::as_witness(t0);
        std::as_witness(t1);
        let t2 = Params::a() * t0 + t1;
        let t3 = 1 + Params::d() * t0 * t1;
        (t2 == t3)
    }

    /// Compute `self + self`
    ///
    /// Cost: 5 gates
    fn dbl(self) -> Self {
        Curve::dbl_internal(self, Params::a(), Params::d())
    }

    /// Compute `self * scalar`
    ///
    /// Uses the Straus method via lookup tables.
    /// Assumes backend has an efficient implementation of a memory table abstraction
    /// i.e. `let x = table[y]` is efficient even if `y` is not known at compile time
    ///
    /// Key cost components are as follows:
    ///      1: computing the Straus point lookup table (169 gates)
    ///      2: 252 point doublings (1260 gates)
    ///      3: 63 point additions (441 gates)
    ///      4: 126 table reads with runtime index (252 gates)
    ///
    /// Cost: 2122 gates + cost of creating ScalarField (110 gates)
    fn mul<let NScalarSlices: u32>(self: Self, scalar: ScalarField<NScalarSlices>) -> Self {
        // define a, d params locally to make code more readable (shouldn't affect performance)
        let a = Params::a();
        let d = Params::d();

        // Construct tables of precomputed point coordinates.
        let (table_x, table_y): ([Field; 16], [Field; 16]) = self.compute_straus_point_table(a, d);

        // Initialize the accumulator with the point that maps to the first (most significant) scalar slice
        let idx = scalar.base4_slices[0] as u32;
        let mut accumulator: Self = Curve { x: table_x[idx], y: table_y[idx] };

        // Execute a double-and-add subroutine
        // 1. Compute `accumulator = accumulator * 16`
        // 2. Extract 4-bits from the scalar multiplier and
        //    use them to retrieve the corresponding point from our point table
        // Note: this is similar to the "double and add" scalar multiplication method, except we use base16 instead of base2!
        for i in 1..NScalarSlices {
            accumulator = accumulator.dbl_internal(a, d);
            accumulator = accumulator.dbl_internal(a, d);
            accumulator = accumulator.dbl_internal(a, d);
            accumulator = accumulator.dbl_internal(a, d);
            let idx = scalar.base4_slices[i] as u32;
            let x = table_x[idx];
            let y = table_y[idx];
            accumulator = accumulator.add_internal(Curve { x, y }, a, d);
        }

        // todo fix
        if (scalar.skew) {
            accumulator = accumulator - self;
        }
        accumulator
    }

    /// compute `points[0] * scalar[0] + ... + points[N-1] * scalar[N-1]`
    ///
    /// Is cheaper than `mul` when processing >1 point due to reduced number of point doublings
    /// uses the Straus MSM method via lookup tables.
    /// Assumes backend has an efficient implementation of a memory table abstraction
    /// i.e. `let x = table[y]` is efficient even if `y` is not known at compile time
    ///
    /// Key cost components are as follows
    /// PER POINT costs:
    ///      1: computing the Straus point lookup table (169N gates)
    ///      2: 63 point additions (441N gates)
    ///      3: 126 table reads with runtime index (252N gates)
    ///
    /// Additional costs:
    ///      1. 252 point doublings 1260 gates
    ///
    /// Cost: 1260 + 862N + cost of creating ScalarField (110N gates)
    fn msm<let N: u32, let NScalarSlices: u32>(
        points: [Self; N],
        scalars: [ScalarField<NScalarSlices>; N],
    ) -> Self {
        let a = Params::a();
        let d = Params::d();

        // Generalized version of `mul` for multiple points.
        let mut point_tables: [([Field; 16], [Field; 16]); N] = [([0; 16], [0; 16]); N];
        for j in 0..N {
            point_tables[j] = points[j].compute_straus_point_table(a, d);
        }

        let idx = scalars[0].base4_slices[0] as u32;
        let mut accumulator: Self = Curve { x: point_tables[0].0[idx], y: point_tables[0].1[idx] };
        for j in 1..N {
            let idx = scalars[j].base4_slices[0] as u32;
            let P = Curve { x: point_tables[j].0[idx], y: point_tables[j].1[idx] };
            accumulator = accumulator.add_internal(P, a, d);
        }
        for i in 1..NScalarSlices {
            accumulator = accumulator.dbl_internal(a, d);
            accumulator = accumulator.dbl_internal(a, d);
            accumulator = accumulator.dbl_internal(a, d);
            accumulator = accumulator.dbl_internal(a, d);
            for j in 0..N {
                let idx = scalars[j].base4_slices[i] as u32;
                let x = point_tables[j].0[idx];
                let y = point_tables[j].1[idx];
                accumulator = accumulator.add_internal(Curve { x, y }, a, d);
            }
        }

        for j in 0..N {
            if (scalars[j].skew == true) {
                accumulator = accumulator - points[j];
            }
        }
        accumulator
    }
}

// ####################################################################################################################
// ####################################################################################################################
// ### H E L P E R    F U N C T I O N S
// ####################################################################################################################
// ####################################################################################################################
impl<Params> Curve<Params> {

    /// add two points together
    ///
    /// This method exists because of a Noir bug where `Params` cannot be accessed by an internal function
    /// called from internal function. e.g. compiler error if `mul` impl tries to call `add` :(
    fn add_internal(self, other: Self, a: Field, d: Field) -> Self {
        let x1 = self.x;
        let x2 = other.x;
        let y1 = self.y;
        let y2 = other.y;
        let (x, y, lambda) = unsafe { __add_unconstrained(x1, x2, y1, y2, a, d) };
        let x1x2 = x1 * x2;
        let x1y2 = x1 * y2;
        std::as_witness(x1x2);
        std::as_witness(x1y2);
        let x_lhs = x * lambda * d + x - x1y2; // equals y1x2
        let y_lhs = y * lambda * -d + y + x1x2 * a; // equals y1y2
        let y1x2 = y1 * x2;
        let y1y2 = y1 * y2;
        std::as_witness(y1x2);
        std::as_witness(y1y2);
        let y1y2x1x2 = y1y2 * x1x2;
        assert(x_lhs == y1x2);
        assert(y_lhs == y1y2);
        assert(y1y2x1x2 == lambda);
        Self { x, y }
    }

    /// add a point to itself
    ///
    /// This method exists because of a Noir bug where `Params` cannot be accessed by an internal function
    /// called from internal function. e.g. compiler error if `mul` impl tries to call `dbl` :(
    fn dbl_internal(self, a: Field, d: Field) -> Self {
        let x1 = self.x;
        let y1 = self.y;
        let (x3, y3, _) = unsafe { __add_unconstrained(x1, x1, y1, y1, a, d) };
        let x1x1a = x1 * x1 * a;
        std::as_witness(x1x1a);
        // t1 = a*x_1^2 + y_1^2
        let t1 = y1 * y1 + x1x1a;
        std::as_witness(t1);
        // t3 = y_3 * (2 - a*x_1^2 + y_1^2) + 2*a*x_1^2
        let t3 = y3 + y3 - t1 * y3 + x1x1a * 2;
        // t3 == t1 implies y_3 * (2 - a*x_1^2 - y_1^2) + 2*a*x_1^2 == a*x_1^2 + y_1^2
        // i.e. y_3 = y_1^2 - a*x_1^2 / (2 - a*x_1^2 - y_1^2)
        assert(t3 == t1);
        let t4 = x1 * y1;
        std::as_witness(t4);
        // x3 * t1 - t4 == t4 implies x_3 * (y_1^2 + a * x_1^2) = 2 * x_1 * y_1
        // i.e. x_3 = 2 * x_1 * y_1 / (y_1^2 + a * x_1^2)
        let t2 = x3 * t1 - t4;
        assert(t2 == t4);
        Self { x: x3, y: y3 }
    }

    /// Compute a 4-bit lookup table of point multiples for the Straus windowed scalar multiplication algorithm.
    ///
    /// Table contains [0, P, 2P, ..., 15P], which is used in the scalar mul algorithm to minimize the total number of required point additions
    ///
    /// It is cheaper to use ([Field; 16], [Field; 16]) than it is ([Curve; 16]).
    /// This is because the compiler will represent [Curve; 16] in 1 ROM array (vs 2 for [Field; 16], [Field; 16]).
    /// This means that any index into the ROM array for [Curve; 16] requires an additional arithmetic gate to process.
    ///
    ///      For example consider `let P: Curve = table[idx]`
    ///      `table` will be a ROM array with 32 elements in it.
    ///      The x-coordinates will be located at `2 * idx`
    ///      The y-coordinates will be located at `2 * idx + 1`
    ///      If `idx` is not known at compile time (for Straus it isnt), 2 arithmetic gates are required to evaluate `2 * idx`, `2 * idx + 1`
    ///      before they can be used as arguments in a memory lookup protocol
    ///
    ///      Now consider `let P_x = table_x[idx]; let P_y = table_y[idx]`
    ///      In this example, `idx` can be directly used as the argument into a memory lookup protocol for both tables.
    ///
    ///      For the Barretenberg backend, the cost of a Read-Only memory lookup is 2 gates,
    ///      so splitting the x/y coordinates into separate tables means that the cost to lookup a point is 4 gates
    ///      2 extra arithmetic gates would increase the cost by 50%, which we avoid by returning `([Field; 16], [Field; 16])` instead of `([Curve; 16])`
    ///
    /// Key cost components are as follows:
    ///      1: Defining two size-16 lookup tables (2 gates per element, 32 elements = 64 gates)
    ///      2: 15 point additions (7 * 5 = 105)
    ///
    /// Total Cost: 169 gates
    fn compute_straus_point_table(self, a: Field, d: Field) -> ([Field; 16], [Field; 16]) {
        let mut table_x: [Field; 16] = [0; 16];
        let mut table_y: [Field; 16] = [0; 16];
        table_x[8] = self.x;
        table_y[8] = self.y;
        let D = self.dbl_internal(a, d);
        for i in 1..8 {
            let Q = Self { x: table_x[7 + i], y: table_y[7 + i] };
            let V = D.add_internal(Q, a, d);
            table_x[8 + i] = V.x;
            table_y[8 + i] = V.y;
        }
        for i in 0..8 {
            table_x[i] = -table_x[15 - i];
            table_y[i] = table_y[15 - i];
        }
        (table_x, table_y)
    }
}

/// add points together, return output + lambda ter
unconstrained fn __add_unconstrained(
    x1: Field,
    x2: Field,
    y1: Field,
    y2: Field,
    a: Field,
    d: Field,
) -> (Field, Field, Field) {
    let lambda = y1 * y2 * x1 * x2;
    let y = (x1 * x2 * a - y1 * y2) / (lambda * d - 1);
    let x = (x1 * y2 + y1 * x2) / (lambda * d + 1);
    (x, y, lambda)
}

